{
 "command": "ls var/cache/search/ && head -c 300 var/cache/search/shard-000.json; echo; git status --short var/ ; git check-ignore var/cache/search && echo ignored",
 "description": "Inspect cached search shards"
}

{
 "command": "python scripts/build_search_index.py --clear-cache && cat var/search/index.json",
 "description": "Rebuild index after clearing stale cache"
}

{
 "type": "hazard",
 "summary": "build_search_index.py 'unexpected token in shard-NNN.json' means stale tokenizer cache; rerun with --clear-cache",
 "content": "Running `python scripts/build_search_index.py` can fail with `index build failed: unexpected token in shard-000.json`. The message is misleading: there's no parse error. Cached shards in var/cache/search/ (git-ignored) were built with an older tokenizer version (e.g. 2), and the script's TOKENIZER constant is now 3. Fix: `python scripts/build_search_index.py --clear-cache`, which deletes the derived cache and rebuilds var/search/index.json.",
 "physical": [
  "scripts/build_search_index.py"
 ],
 "invalidated_by": [
  "scripts/build_search_index.py"
 ],
 "epistemic": "observation",
 "tags": [
  "search-index",
  "cache"
 ]
}
